#include "quadratic.hpp"
struct InputCase{std::string name;F r;Poly b0,b1,c0,c1,g;};
std::vector<InputCase> loadCases(){std::vector<InputCase>o;for(std::string type:{"double","critical"})for(int r:{145049,211895,211959}){InputCase c;c.name=type+"_"+std::to_string(r);std::ifstream f("regenerated/"+type+"_content_"+std::to_string(r)+".dat");std::string h;f>>h>>c.r;if(h!="DOUBLE_CONTENT_V1")throw std::runtime_error("bad incidence");c.b0=readpoly(f);c.b1=readpoly(f);c.c0=readpoly(f);c.c1=readpoly(f);c.g=readpoly(f);o.push_back(c);}return o;}
void one(const std::vector<Record>&records,const InputCase&cs,Poly g){if(g.deg()<=0)return;AE::modulus=g;try{AE v(Poly::mon(1)),q=scale(v.pow(-3),eval(P,cs.r)),H=-peval(cs.b0,v)/peval(cs.b1,v);AE a0=peval(a0poly(),q),psi=a0+H*q*(AE(299833)+scale(q,232505));AE open=H*q*psi*(q-AE(15383))*(q-AE(1))*a0;Poly rejected=gcd(g,open.p);if(rejected.deg()>0){std::cout<<cs.name<<" excluded original open degree "<<rejected.deg()<<"\n";one(records,cs,exactdiv(g,rejected));return;}auto E=evalE(records,H,q);std::array<int,3>val;std::array<EP,3>leads;for(int j=0;j<3;j++){auto jets=endpointJets(E,cs.r,scale(v,ff::pow(11,j)),21);val[j]=valJets(jets);leads[j]=jetLead(jets,val[j]);}
std::cout<<cs.name<<" modulusdeg "<<g.deg()<<" local_orders "<<val[0]<<","<<val[1]<<","<<val[2]<<" lead_mu_degrees "<<int(leads[0].size())-1<<","<<int(leads[1].size())-1<<","<<int(leads[2].size())-1<<"\n";std::cout.flush();std::string file="regenerated/"+cs.name+"_jets_"+std::to_string(g.at(0))+".dat";std::ofstream out(file);out<<"HIGH_CONTENT_JETS_V1\n"<<cs.name<<"\n"<<cs.r<<"\n";writepoly(out,g);writeA(out,H);writeA(out,q);for(int j=0;j<3;j++){out<<val[j]<<"\n";writeEP(out,leads[j]);}
int n=val[0]+val[1]+val[2];if(n%2){for(int j=0;j<3;j++){if(leads[j].size()==1){leads[j][0].inverse();continue;}if(leads[j].size()==3){AE ilc=leads[j][2].inverse();QE::S=-leads[j][1]*ilc;QE::T=-leads[j][0]*ilc;auto W=qevalW(E,q);auto errors=errorsQ(W,73);int good=-1;for(int e=0;e<int(errors.size());e++){Poly ng=gcd(g,errors[e].norm().p);if(ng.deg()==0){good=e;break;}}if(good<0)throw std::runtime_error("quadratic candidate not excluded");QE inv=errors[good].inverse();if(!(errors[good]*inv==QE(1)))throw std::runtime_error("quadratic unit check failed");out<<"quadratic_candidate "<<j<<" "<<71+good<<"\n";writeA(out,QE::S);writeA(out,QE::T);writeQ(out,errors[good]);writeQ(out,inv);std::cout<<"quadratic candidate sheet "<<j<<" excluded by unit C"<<71+good<<"\n";continue;}if(leads[j].size()!=2)throw std::runtime_error("higher degree candidate remains");AE mu=-leads[j][0]/leads[j][1];Poly atzero=gcd(g,mu.p);if(atzero.deg()>0){if(atzero.deg()==g.deg()){std::cout<<"zero-scale candidate only\n";continue;}throw SplitNeeded(atzero);}auto W=evalW(E,mu,q);auto errors=errorsA(W,73);Poly survive=apGCD(errors);int good=-1;for(int e=0;e<int(errors.size());e++)if(gcd(g,errors[e].p).deg()==0){good=e;break;}std::cout<<"candidate sheet "<<j<<" early_equations common degree "<<survive.deg()<<" first unit "<<(good<0?-1:71+good)<<"\n";if(good<0)throw std::runtime_error("no individual linear unit");AE eu=errors[good].inverse();if(!(errors[good]*eu==AE(1)))throw std::runtime_error("linear unit product failed");out<<"candidate "<<j<<"\n";writeA(out,mu);for(auto&e:errors)writeA(out,e);writepoly(out,survive);out<<"unit "<<71+good<<"\n";writeA(out,eu);if(survive.deg()>0)throw std::runtime_error("candidate not excluded");}std::cout<<"EXCLUDED all scales on odd-content stratum "<<cs.name<<" degree "<<g.deg()<<"\n";}else std::cout<<"EVEN CONTENT remains\n";
}catch(const SplitNeeded&e){std::cout<<cs.name<<" split modulus "<<g.deg()<<" -> "<<e.factor.deg()<<" + "<<g.deg()-e.factor.deg()<<"\n";if(e.factor.deg()<=0||e.factor.deg()>=g.deg())throw;one(records,cs,e.factor);one(records,cs,exactdiv(g,e.factor));}}
int main(){try{ff::init();init_source();auto records=load("inputs/E_records.tsv");for(auto cs:loadCases())one(records,cs,cs.g);return 0;}catch(const std::exception&e){std::cerr<<"ERROR "<<e.what()<<"\n";return 1;}}
